import { useEffect, useState } from "react";
import axios from "axios";

function Index() {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchGames = async () => {
      try {
        const response = await axios.post(
          "http://localhost:3001/api/igdb/games",
          {
            query: `fields name, cover.url, rating, genres.name;
                    sort rating desc;
                    limit 15;`,
          }
        );
        setGames(response.data);
      } catch (error) {
        console.error("Error al traer juegos:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchGames();
  }, []);

  if (loading) return <p>Cargando...</p>;

  return (
    <div className="movies-info">
      {games.map((game) => (
        <div className="desc_title">

          {game.cover && (
            <img
              src={`https:${game.cover.url.replace("t_thumb", "t_cover_big")}`}
              alt={game.name}
            />
          )}
          <p>Rating: {game.rating?.toFixed(1)}</p>
        </div>
      ))}
    </div>
  );
}

function MovieCard({ movie, onFavorite, onHistorial, onDetails}) {
  const imagen = movie.Poster !== "N/A" ? movie.Poster : "img/Image-not-found.png";

  return (
    <div className="movie-card">
       <img
              src={`https:${game.cover.url.replace("t_thumb", "t_cover_big")}`}
              alt={game.name}
        />      

      <div className="desc_title">
        <h4>{game.name}</h4>        
      </div>

    </div>
  );
}

export default Index;
